export const Controlled = {
  args: {},
  render: args => {
    const [value, setValue] = React.useState(["accordion-2"]);
    const onValueChange = React.useCallback(nextValue => {
      setValue(nextValue);
    }, []);
    return renderAccordion({
      ...args,
      value,
      onValueChange
    }, {
      items
    });
  }
};
export const Accessibility = {
  args: {
    defaultValue: ["accordion-1"]
  },
  render: args => renderAccordion(args, {
    items
  }),
  play: async ({
    canvasElement,
    step
  }) => {
    const canvas = within(canvasElement);
    const firstTrigger = await canvas.getByRole("button", {
      name: /Accordion 1/i
    });
    await step("Arrow keys move focus between triggers", async () => {
      firstTrigger.focus();
      await userEvent.keyboard("{ArrowDown}");
      const secondTrigger = await canvas.getByRole("button", {
        name: /Accordion 2/i
      });
      await expect(secondTrigger).toHaveFocus();
    });
    await step("Enter toggles the focused panel", async () => {
      await userEvent.keyboard("{Enter}");
      const secondTrigger = await canvas.getByRole("button", {
        name: /Accordion 2/i
      });
      await expect(secondTrigger).toHaveAttribute("aria-expanded", "true");
    });
  }
};